        `bestIdx=${movementAuthorityDecision.bestIdx}`,
        `bestSim=${formatLogScore(movementAuthorityDecision.bestSim)}`,
        `authority=${movementAuthority}`,
        `reason=${movementAuthorityReason}`,
        movementAuthorityDecision.proofSource
